try {
const c = window.replyCfg && window.replyCfg();
const n = c ? Number(c['mjf-pub']) : NaN;
if (c && c['mjf-pub'] != null && c['mjf-pub'] !== '' && Number.isFinite(n)) pubProb = Math.max(0, Math.min(100, n));
} catch (e) {}
const usePublic = Math.random() * 100 < pubProb;
