if (day === 0 && now.getHours() >= 18) {
sun = cur;
} else {
const back = ((day + 6) % 7) + 1; // 距上一个周日 1~7 天（周一=2 … 周六=7）
if (back < 2 || back > 4) return; // 只补最近一周：周一~周三内补发
sun = new Date(cur.getFullYear(), cur.getMonth(), cur.getDate() - back);
}
