if (existing.length >= 3 && existing[0].parentNode) existing[0].parentNode.removeChild(existing[0]);
const splash = document.createElement('div');
splash.className = 'fish-splash' + (got ? ' ok' : '');
splash.textContent = got ? (item ? item.icon : '🐟') : '💨';
