try { localStorage.setItem(FREQ_KEY, JSON.stringify(freq)); } catch (e) { /* 存储满不影响跳转 */ }
if (typeof window.idbSet === 'function') { try { window.idbSet(FREQ_KEY, freq).catch(() => {}); } catch (e) {} }
